{
  "description": "The creature is shown in right-facing profile standing upright on two hind legs against a plain off-white background. The upper portion including the head, ears, and muzzle is that of a red fox with reddish-orange fur, while the neck, chest, and sides of the torso are covered in pale owl-like plumage with dark speckling, and a pair of large folded wings with mottled brown, tan, grey and white patterning rests along the back and sides. The lower body, hindquarters and long bushy tail are again fox-like with dense reddish-brown fur and a white tail tip. The overall posture is upright and alert, with the head turned slightly to the right and the tail extending horizontally behind the body.",
  "parts": [
    {
      "part": "head",
      "looks_like": "fox-like with a narrow pointed muzzle, black nose, amber-brown eyes, white fur on the muzzle, chin and throat, and reddish-orange fur on the forehead, cheeks and top of the head, with fine whiskers at the muzzle",
      "where": "at the top front of the body, facing to the right"
    },
    {
      "part": "ears",
      "looks_like": "two large triangular upright ears with pointed dark tips, reddish-orange outer fur and cream to light brown inner fur with darker edges",
      "where": "on top of the head, one slightly behind the other in profile view"
    },
    {
      "part": "legs",
      "looks_like": "two muscular hind legs covered in dense reddish-brown fur with lighter cream fur on the inner thigh and lower leg, bent at the knee and hock in a standing crouch",
      "where": "under the torso extending from the lower body to the ground, visible in side view"
    },
    {
      "part": "feet",
      "looks_like": "paw-like feet with short dark claws and padded soles, covered in short brown fur with darker toes",
      "where": "at the bottom ends of the two hind legs resting on the ground"
    },
    {
      "part": "tail",
      "looks_like": "long, thick and bushy with dense reddish-brown fur that becomes white at the tip, with a slightly darker underside",
      "where": "at the rear of the body behind the hind legs, extending horizontally to the left"
    },
    {
      "part": "wings",
      "looks_like": "two large folded wings with rounded edges, the right wing fully visible and the left wing partially visible behind the chest",
      "where": "attached along the sides of the torso from the shoulder area down to about mid-thigh, folded against the body"
    },
    {
      "part": "feathers",
      "looks_like": "layered feathers in mottled tan, warm brown, grey and white with intricate barring and spotting; wing feathers show broad bars and eye-like spots, chest feathers are soft and fluffy",
      "where": "covering the wings and the front of the neck, chest and upper belly"
    },
    {
      "part": "markings",
      "looks_like": "small scattered black dots on the white chest, throat and neck, and darker brown and black bars and spots forming a mottled pattern on the wing feathers",
      "where": "on the pale chest, throat, neck and across the wing surfaces"
    }
  ],
  "attached_objects": [],
  "animals": [
    "fox",
    "owl"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 2,
  "wings": 2,
  "extra_limb_pieces": 0,
  "tails": 1
}
